from pyspark.sql import functions as F


def solve(transactions):
    rules = [
        ("missing_account", F.col("account_id").isNotNull()),
        ("bad_amount", F.col("amount") > 0),
        ("unknown_currency", F.col("currency").isin("USD", "EUR", "GBP")),
        ("unknown_status", F.col("status").isin("posted", "pending", "declined")),
    ]
    for name, passes in rules:
        reason = F.when(~passes, name)
    checked = transactions.select("transaction_id", "account_id", "amount", "currency", reason.alias("reason"))
    return checked.filter(F.col("reason").isNotNull())
